namespace App\Modules\Contracts\Infrastructure;

use App\Platform\Audit\AuditLogger;
use App\Platform\Queue\JobContext;
use App\Platform\Queue\JobHandlerInterface;
use Yiisoft\Db\Connection\ConnectionInterface;

/**
 * Job `contracts.cleanup`: permanently removes contracts that were soft-deleted more than `retention_days`
 * (payload, default 90, minimum 1) ago. Works in batches of 500 inside short transactions, honours
 * cancellation, reports progress and writes one audit record with the number of purged rows.
 * Idempotent: re-running only finds what is still eligible.
 */
final class PurgeDeletedContractsJob implements JobHandlerInterface
{
    public const TYPE = 'contracts.cleanup';
    public const DEFAULT_RETENTION_DAYS = 90;
    private const BATCH = 500;

    public function __construct(
        private readonly ConnectionInterface $db,
        private readonly AuditLogger $audit,
    ) {}

    public function handle(array $payload, JobContext $context): void
    {
        $days = max(1, (int) ($payload['retention_days'] ?? self::DEFAULT_RETENTION_DAYS));
        $total = (int) $this->db->createCommand(
            "SELECT count(*) FROM contracts WHERE deleted_at IS NOT NULL AND deleted_at < now() - make_interval(days => :d)",
            [':d' => $days],
        )->queryScalar();
        $purged = 0;
        while (true) {
            $context->throwIfCancelled();
            $n = (int) $this->db->transaction(fn() => $this->db->createCommand(
                "DELETE FROM contracts WHERE id IN (
                    SELECT id FROM contracts WHERE deleted_at IS NOT NULL AND deleted_at < now() - make_interval(days => :d)
                    ORDER BY deleted_at LIMIT " . self::BATCH . ' FOR UPDATE SKIP LOCKED)',
                [':d' => $days],
            )->execute());
            $purged += $n;
            if ($total > 0) {
                $context->progress((int) min(99, floor($purged / $total * 100)));
            }
            if ($n < self::BATCH) {
                break;
            }
        }
        $this->audit->record('contract.purged', 'contract', null, null, ['purged' => $purged], ['retention_days' => $days], category: 'data', severity: 'notice');
        $context->progress(100);
    }
}
